#include <memory>
#include <iostream>

class Resource { 
public:
    Resource() { std::cout << "Allocated\n"; }
    ~Resource() { std::cout << "Destroyed\n"; }
};

void safe_function() {
    // auto_ptr guarantees destruction even if 'throw' occurs
    std::auto_ptr<Resource> ptr(new Resource);
    // ... operations that might throw ...
    // Resource is automatically destroyed upon scope exit.
}
